  if (m < 1.5) { return clamp(c * e, vec3f(0.0), vec3f(1.0)); }
  if (m < 2.5) { let x = c * e; return clamp(x / (1.0 + x), vec3f(0.0), vec3f(1.0)); }
  if (m > 6.5) { return clamp(neutralTM(c * e), vec3f(0.0), vec3f(1.0)); }
