    let ab = B - A.xyz; let len = length(ab); let u = ab / max(len, 1e-5);
    let t = dot(p - A.xyz, u); let q = A.xyz + u * clamp(t, 0.0, len); let dv = q - p; let dq = length(dv);
    let c = dot(n, dv) / max(dq, 1e-4); if (c <= 0.0) { continue; }
